package com.johnny.hotel.payroll;import com.johnny.hotel.entity.*;import com.johnny.hotel.mapper.*;import lombok.RequiredArgsConstructor;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import java.util.*;import java.util.stream.*;
@Component@RequiredArgsConstructor public class PayrollAccess{private final SysUserMapper users;private final SysRoleMapper roles;public record Actor(Long id,Set<String>roles){boolean has(String...r){return Arrays.stream(r).anyMatch(roles::contains);}}
 public Actor actor(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated()||!(a.getDetails() instanceof Long id))throw denied();var u=users.selectById(id);var rs=roles.selectRolesByUserId(id).stream().map(SysRole::getRoleCode).collect(Collectors.toSet());if(u==null||!Integer.valueOf(1).equals(u.getStatus())||rs.contains("CUSTOMER"))throw denied();return new Actor(id,rs);}
 void hr(Actor a){if(!a.has("HR_ADMIN","OWNER","SUPER_ADMIN"))throw denied();}void owner(Actor a){if(!a.has("OWNER","SUPER_ADMIN"))throw denied();}void finance(Actor a){if(!a.has("FINANCE","OWNER","SUPER_ADMIN"))throw denied();}AccessDeniedException denied(){return new AccessDeniedException("Payroll access denied");}}
